1	import { useState } from 'react';
2	import { Link } from '@tanstack/react-router';
3	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
4	import { getJson, postJson } from '../../api/http';
5	import { asString, useSearchParam } from '../../url/useSearchParam';
6	import { InvoicesToolbar } from '../../slots/defs/invoicesToolbar';
7	import { InvoiceRowCells } from '../../slots/defs/invoiceRowCells';
8	import { money } from '../../ui/money';
9	import { invoiceStatus } from '../../ui/invoiceStatus';
10	
11	// An invoice as the server returns it: which project it belongs to, its amount, and its lifecycle
12	// status (DRAFT until sent, SENT until paid, then PAID).
13	export type Invoice = {
14	  id: number;
15	  projectId: number;
16	  amount: number;
17	  status: string;
18	  issuedDate: string;
19	  dueDate: string;
20	  // How much is still owed after payments (amount minus every payment recorded against it), derived
21	  // and sent by the server. The amount-due cell (features/invoices/dueAmount.slot.tsx) reads this.
22	  amountDue: number;
23	};
24	
25	// A project's invoices: the list scoped to this project, their derived total, and the form to add a
26	// new one. Server data is read with useQuery under the ['invoices'] key and changed with
27	// useMutation + invalidateQueries — never copied into state, never hand-maintained. The only
28	// useState is the amount the user is currently typing (rule 4).
29	export function InvoicesPanel({ projectId }: { projectId: number }) {
30	  const queryClient = useQueryClient();
31	  // The sort lives in the URL (owned by features/invoices/sortByDue.slot.tsx). The panel reads the
32	  // same key and asks the server for the ordered list, so it stays a single source of truth — no
33	  // server data copied into state or re-sorted by hand. The key still starts with 'invoices', so
34	  // writes that invalidateQueries({ queryKey: ['invoices'] }) still refresh it.
35	  const [sort] = useSearchParam('invoiceSort', asString);
36	  const invoices = useQuery({
37	    queryKey: ['invoices', sort],
38	    queryFn: () =>
39	      getJson<Invoice[]>(
40	        sort ? `/api/invoices?sort=${encodeURIComponent(sort)}` : '/api/invoices',
41	      ),
42	  });
43	
44	  const [amount, setAmount] = useState('');
45	  const [error, setError] = useState('');
46	
47	  const create = useMutation({
48	    mutationFn: () =>
49	      postJson<Invoice>('/api/invoices', { projectId, amount: Number(amount) }),
50	    onSuccess: () => {
51	      setAmount('');
52	      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
53	    },
54	  });
55	
56	  // Sending a draft invoice is a write: POST then invalidate ['invoices'] so the row re-renders with
57	  // its new status (DRAFT -> SENT) — never hand-maintained. The server also records the send to the
58	  // audit file.
59	  const send = useMutation({
60	    mutationFn: (id: number) => postJson<Invoice>('/api/invoices/send', { id }),
61	    onSuccess: () => {
62	      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
63	    },
64	  });
65	
66	  const rows = (invoices.data ?? []).filter((i) => i.projectId === projectId);
67	  const total = rows.reduce((sum, i) => sum + Number(i.amount), 0);
68	
69	  return (
70	    <section data-testid="project-invoices">
71	      <form
72	        data-testid="invoice-form"
73	        onSubmit={(e) => {
74	          e.preventDefault();
75	          const value = Number(amount);
76	          if (!amount.trim() || Number.isNaN(value) || value <= 0) {
77	            setError('Amount must be more than zero.');
78	            return;
79	          }
80	          setError('');
81	          create.mutate();
82	        }}
83	      >
84	        <input
85	          data-testid="invoice-form-amount"
86	          type="number"
87	          step="0.01"
88	          placeholder="Amount"
89	          value={amount}
90	          onChange={(e) => {
91	            setAmount(e.target.value);
92	            setError('');
93	          }}
94	        />
95	        <button data-testid="invoice-form-submit" type="submit">
96	          Add invoice
97	        </button>
98	        {error && (
99	          <p data-testid="invoice-form-amount-error" role="alert">
100	            {error}
101	          </p>
102	        )}
103	      </form>
104	
105	      <div data-testid="project-invoices-toolbar">
106	        <InvoicesToolbar.Slot />
107	      </div>
108	
109	      <table data-testid="project-invoices-table">
110	        <thead>
111	          <tr>
112	            <th>Amount</th>
113	            <th>Amount due</th>
114	            <th>Issued</th>
115	            <th>Due</th>
116	            <th>Status</th>
117	            <th></th>
118	          </tr>
119	        </thead>
120	        <tbody>
121	          {rows.map((i) => (
122	            <tr key={i.id} data-testid={`invoice-row-${i.id}`}>
123	              <td data-testid="invoice-amount">{money(Number(i.amount))}</td>
124	              <InvoiceRowCells.Slot invoiceId={i.id} />
125	              <td data-testid="invoice-issued">{i.issuedDate}</td>
126	              <td data-testid="invoice-due">{i.dueDate}</td>
127	              <td data-testid="invoice-status">{invoiceStatus(i)}</td>
128	              <td>
129	                <Link
130	                  to="/invoice/$invoiceId"
131	                  params={{ invoiceId: String(i.id) }}
132	                  data-testid={`invoice-open-${i.id}`}
133	                >
134	                  Open
135	                </Link>
136	                {i.status === 'DRAFT' && (
137	                  <button
138	                    type="button"
139	                    data-testid={`invoice-send-${i.id}`}
140	                    onClick={() => send.mutate(i.id)}
141	                  >
142	                    Send
143	                  </button>
144	                )}
145	              </td>
146	            </tr>
147	          ))}
148	        </tbody>
149	        <tfoot>
150	          <tr>
151	            <td data-testid="project-invoices-total">{money(total)}</td>
152	          </tr>
153	        </tfoot>
154	      </table>
155	    </section>
156	  );
157	}
158

