2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Consumer;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Domain tables in FK-dependency order (child before parent). Referential integrity is dropped
34	     * around the truncates so the order is not load-bearing, but keeping it sensible documents the
35	     * shape. A new table joins the reset by being added to this list — no new statement to write.
36	     */
37	    private static final List<String> DOMAIN_TABLES =
38	            List.of("note", "project_tag", "tag", "payment", "line_item", "invoice", "task",
39	                    "contact", "project", "client");
40	
41	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
42	    @PostMapping("/reset")
43	    public void reset() {
44	        audit.clear();
45	        // Drop referential integrity around the truncates: RESTART IDENTITY on each, then restore
46	        // it. That makes the order above cosmetic and clears every FK-referenced table cleanly.
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
48	        for (String table : DOMAIN_TABLES) {
49	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
50	        }
51	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	    }
53	
54	    /**
55	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Each table is one
56	     * {@link #seedRows} call: name the fixture key, then map a row to an INSERT. A new table is one
57	     * more call here — the null-check and per-row loop are shared, not repeated.
58	     */
59	    @PostMapping("/seed")
60	    public void seed(@RequestBody Map<String, Object> fixture) {
61	        seedRows(fixture, "clients", c -> jdbc.update(
62	                "INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
63	                asLong(c, "id"), c.get("name"), c.get("email")));
64	
65	        seedRows(fixture, "projects", p -> jdbc.update(
66	                "INSERT INTO project (id, name, client_id) VALUES (?, ?, ?)",
67	                asLong(p, "id"), p.get("name"), asLong(p, "clientId")));
68	
69	        seedRows(fixture, "tasks", t -> jdbc.update(
70	                "INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
71	                asLong(t, "id"), asLong(t, "projectId"), t.get("title"),
72	                Boolean.TRUE.equals(t.get("done"))));
73	
74	        seedRows(fixture, "tags", t -> jdbc.update(
75	                "INSERT INTO tag (id, name) VALUES (?, ?)",
76	                asLong(t, "id"), t.get("name")));
77	
78	        // A project_tag row is a (project, tag) pairing with no id of its own in the fixture — let the
79	        // IDENTITY column assign one (GENERATED BY DEFAULT allows the omission).
80	        seedRows(fixture, "projectTags", pt -> jdbc.update(
81	                "INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
82	                asLong(pt, "projectId"), asLong(pt, "tagId")));
83	
84	        seedRows(fixture, "notes", n -> jdbc.update(
85	                "INSERT INTO note (id, target_type, target_id, note_text, created_at) "
86	                        + "VALUES (?, ?, ?, ?, ?)",
87	                asLong(n, "id"), n.get("targetType"), asLong(n, "targetId"),
88	                n.get("text"), n.get("at")));
89	        // The seed inserts explicit ids into note's IDENTITY column (GENERATED BY DEFAULT), which does
90	        // not advance the identity sequence — reset RESTARTed it at 1. Without this the first app-side
91	        // save() would regenerate id=1 and collide with a seeded row. Advance it past the max seeded
92	        // id so a note added through the API (POST /api/notes) gets a fresh id.
93	        syncIdentity("note");
94	
95	        seedRows(fixture, "contacts", c -> jdbc.update(
96	                "INSERT INTO contact (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
97	                asLong(c, "id"), asLong(c, "clientId"),
98	                c.get("name"), c.get("email"), c.get("role")));
99	
100	        // An invoice is now itemised: its amount is the sum of qty * unit price across its lines
101	        // (nested under the invoice in the fixture). The stored amount is the derived total — the
102	        // fixture may still supply an explicit "amount" for an invoice with no lines, otherwise it
103	        // is computed here so the invoice list reads the same total the lines add up to.
104	        seedRows(fixture, "invoices", i -> {
105	            List<Map<String, Object>> lines = asRows(i.get("lineItems"));
106	            double computed = 0;
107	            for (Map<String, Object> li : lines) {
108	                computed += ((Number) li.get("qty")).doubleValue()
109	                        * ((Number) li.get("unitPrice")).doubleValue();
110	            }
111	            Object explicit = i.get("amount");
112	            double amount = explicit == null ? computed : ((Number) explicit).doubleValue();
113	            jdbc.update(
114	                    "INSERT INTO invoice (id, project_id, amount, status, issued_date, due_date) "
115	                            + "VALUES (?, ?, ?, ?, ?, ?)",
116	                    asLong(i, "id"), asLong(i, "projectId"), amount,
117	                    i.get("status") == null ? "UNPAID" : i.get("status"),
118	                    i.get("issuedDate"), i.get("dueDate"));
119	            for (Map<String, Object> li : lines) {
120	                jdbc.update(
121	                        "INSERT INTO line_item (id, invoice_id, description, qty, unit_price) "
122	                                + "VALUES (?, ?, ?, ?, ?)",
123	                        asLong(li, "id"), asLong(i, "id"), li.get("description"),
124	                        ((Number) li.get("qty")).intValue(),
125	                        ((Number) li.get("unitPrice")).doubleValue());
126	            }
127	        });
128	
129	        // A payment a client has made against an invoice: how much and on what day. Seeded at the
130	        // fixture's explicit id (GENERATED BY DEFAULT allows it); syncIdentity below advances the
131	        // sequence so an app-side save() (POST /api/payments) gets a fresh id.
132	        seedRows(fixture, "payments", p -> jdbc.update(
133	                "INSERT INTO payment (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
134	                asLong(p, "id"), asLong(p, "invoiceId"),
135	                ((Number) p.get("amount")).doubleValue(), p.get("date")));
136	        syncIdentity("payment");
137	    }
138	
139	    /** A nested optional list of rows (e.g. an invoice's line items), or empty when the key is absent. */
140	    @SuppressWarnings("unchecked")
141	    private static List<Map<String, Object>> asRows(Object value) {
142	        return value == null ? List.of() : (List<Map<String, Object>>) value;
143	    }
144	
145	    /**
146	     * Run {@code insert} for each row under {@code key}, or do nothing if the fixture omits that key.
147	     * This is the shared "optional list of rows" shape every table seed follows.
148	     */
149	    @SuppressWarnings("unchecked")
150	    private void seedRows(Map<String, Object> fixture, String key,
151	            Consumer<Map<String, Object>> insert) {
152	        List<Map<String, Object>> rows = (List<Map<String, Object>>) fixture.get(key);
153	        if (rows == null) {
154	            return;
155	        }
156	        for (Map<String, Object> row : rows) {
157	            insert.accept(row);
